from pathlib import Path
import subprocess

def safe_child(root: Path, requested_name: str) -> Path:
    root = root.resolve()
    candidate = (root / requested_name).resolve()
    if root not in candidate.parents and candidate != root:
        raise ValueError('requested file is outside the allowed directory')
    return candidate

def convert(root: Path, requested_name: str, output: Path) -> None:
    source = safe_child(root, requested_name)
    if not source.is_file():
        raise ValueError('requested file does not exist')
    subprocess.run(
        ['converter', '--input', str(source), '--output', str(output)],
        check=True, timeout=30, shell=False,
    )

